mapper.select:
SELECT DATE(start_time) AS day, IFNULL(SUM(fee), 0) AS income FROM course
WHERE user_id = #{userId} AND status = 'completed' AND start_time >= #{start} AND start_time < #{end}
GROUP BY DATE(start_time) ORDER BY day

SELECT c.subject AS name, IFNULL(SUM(c.fee), 0) AS value FROM course c
WHERE c.user_id = #{userId} AND c.status = 'completed' AND c.start_time >= #{start} AND c.start_time < #{end}
GROUP BY c.subject ORDER BY value DESC
